configuration.msdyn_runconfigschema:
[
  {
    "name": "numberOfIndividualPredictors",
    "displayName": "Number of instance level predictors",
    "description": "Defines the number of instance level predictors to be output during scoring",
    "defaultValue": "3",
    "type": "Edm.Int32"
  },
  {
    "name": "isCustomPipelinesEnabled",
    "displayName": "Is Custom Pipelines enabled for run",
    "description": "Defines if the AI Config is enabled for Custom Pipelines",
    "defaultValue": "True",
    "type": "Edm.Boolean"
  },
  {
    "name": "customPipelineYaml",
    "displayName": "Custom Pipeline Yaml",
    "description": "Defines the yaml file to be used for inference",
    "defaultValue": "GP-Inference-Pipeline.yaml",
    "type": "Edm.String"
  }
]
